static partial class Tests
{
 static long count;static void Eq(long e,long a,string m){count++;if(e!=a)throw new Exception(m+": expected "+e+" got "+a);}static void Yes(bool v,string m){count++;if(!v)throw new Exception(m);}static byte B(int n){return unchecked((byte)n);}static ushort W(int n){return unchecked((ushort)n);}
 static void Private(Type t,string field,object v){t.GetField(field,BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,v);}
 sealed class Bus:ISoundPortBus{public List<int[]> Writes=new List<int[]>();public byte Value;public byte Read(ushort p){return Value;}public void Write(ushort p,byte v){Writes.Add(new[]{(int)p,(int)v});}}
 sealed class Platform:ISoundTimerPlatform{public Action TimerVector{get;set;}public byte[] Message;public int Code;public void GetTime(out ushort h,out ushort m,out ushort s,out ushort c){h=23;m=59;s=58;c=99;}public void Shutdown(byte[] message,byte code){Message=message;Code=code;throw new EndProcess();}}
 sealed class EndProcess:Exception{}
 static void Crc(ref uint crc,int b){crc^=(byte)b;for(int i=0;i<8;i++)crc=(crc>>1)^((crc&1)!=0?0xEDB88320u:0);}
 static void SoundGolden()
 {
  // These are the pre-refactor SSI trace records, not outputs generated by this managed interpreter.
  var records=SoundGoldenRecords.Rows;
  foreach(var r in records){int dev=int.Parse(r[0]),tune=int.Parse(r[1]);var bus=new Bus();var d=new SoundDriver(bus,new Platform());d.SetSoundDevice(W(dev));if(dev==1)d.ProgramSpeakerVoices(W(tune));else d.ProgramTandyVoices(W(tune));uint crc=0xFFFFFFFF;int ticks=0,writes=0;do{bus.Writes.Clear();d.TraceTick();ticks++;writes+=bus.Writes.Count;Crc(ref crc,bus.Writes.Count);foreach(var w in bus.Writes){Crc(ref crc,w[0]&255);Crc(ref crc,w[1]);}}while(d.State.VoiceTune.Any(x=>x!=0)&&ticks<6000);Eq(int.Parse(r[2]),ticks,"SSI ticks dev"+dev+" tune"+tune);Eq(int.Parse(r[3]),writes,"SSI writes dev"+dev+" tune"+tune);Eq(Convert.ToUInt32(r[4],16),crc,"SSI trace CRC dev"+dev+" tune"+tune);}
 }
 static void SoundTimer()
 {
  var bus=new Bus{Value=255};var p=new Platform();int chains=0;p.TimerVector=()=>chains++;Action old=p.TimerVector;var d=new SoundDriver(bus,p);
  d.InstallSoundTimer();Yes(d.Hooked,"timer hooked");Yes(p.TimerVector!=old,"vector changed");Yes(bus.Writes.Select(x=>x[0]+":"+x[1]).SequenceEqual(new[]{"67:182","67:54","64:177","64:19"}),"PIT install sequence");d.InstallSoundTimer();Eq(4,bus.Writes.Count,"idempotent hook");bus.Writes.Clear();for(int i=0;i<12;i++)p.TimerVector();Eq(0,chains,"BIOS initial boundary before13");p.TimerVector();Eq(1,chains,"BIOS initial boundary at13");for(int i=0;i<65536;i++)p.TimerVector();Eq(5042,chains,"BIOS each13 ticks");Eq(13,d.Ticks,"tick word wrap");Eq(60507,bus.Writes.Count,"only nonchained EOI");Yes(bus.Writes.All(x=>x[0]==32&&x[1]==32),"PIC EOI port/value");
  bus.Writes.Clear();d.UninstallSoundTimer();Yes(!d.Hooked&&p.TimerVector==old,"restores displaced vector");Yes(bus.Writes.Select(x=>x[0]+":"+x[1]).SequenceEqual(new[]{"67:54","64:0","64:0","97:252"}),"PIT restore/gates no Tandy writes forNone");d.UninstallSoundTimer();Eq(4,bus.Writes.Count,"idempotent unhook");
  d.SetSoundDevice(257);Eq(1,d.Device,"mode low byte");bus.Writes.Clear();d.SetSoundDevice(99);Eq(2,d.Device,"invalid mode None");Eq(97,bus.Writes.Single()[0],"leaving speaker clears gate");d.SetSoundOutputEnabled(256);Eq(0,d.State.OutputOn,"output flag low byte");d.State.VoiceTune[3]=82;Eq(82,d.SoundVoiceTune(65535),"voice index modulo4");d.ExitCount=1;try{d.Interrupt();throw new Exception("shutdown missing");}catch(EndProcess){}Eq(255,p.Code,"exit code");Eq(33,p.Message.Length,"message count");Yes(p.Message.All(x=>x<128),"message high bits stripped");
  var busy=new SoundDriver(new Bus(),new Platform());busy.SetSoundDevice(1);busy.ProgramSpeakerVoices(1);busy.State.SequenceBusy=7;busy.TraceTick();Eq(7,busy.State.SequenceBusy,"busy skip preserves value");Eq(1,busy.Speaker.Voices[0].Duration,"busy no step");
 }
 static SoundArrangement Data(params byte[] stream){var data=new byte[4096];Array.Copy(stream,0,data,1024,stream.Length);return new SoundArrangement(data,new ushort[29,4],Enumerable.Range(0,12).Select(i=>W(24000-i*100)).ToArray(),new Dictionary<string,ushort>());}
 sealed class TestSeq:FourVoiceSequencer{public TestSeq(SoundArrangement a):base(new Bus(),new SoundSequenceState(),a){}public override void Tick(){}}
 static void SoundCore()
 {
  var driver=new SoundDriver(new Bus(),new Platform());var rng=new Random(312);
  for(int k=0;k<20000;k++){
   var a=Data();var seq=new TestSeq(a);var v=seq.Voices[0];v[0]=100;v[4]=W(rng.Next(65536));v[6]=W(rng.Next(65536));v[10]=W(rng.Next(65536));v[12]=W(rng.Next(65536));v[30]=W(rng.Next(8192));v[32]=W(rng.Next(512));v[36]=4096;v[28]=2300;v[34]=W(rng.Next(65536));for(int i=0;i<600;i++)a.Data[2300+i]=B(rng.Next(256));int phase=(v[30]+v[32])%65536;int sample=0;if(phase!=0){if(phase>=4096)phase-=4096;sample=unchecked((sbyte)a.Data[2300+phase/16]);}int expectedLevel=(v[10]+v[12])%65536,period=(v[4]+v[6])%65536;int delta=(int)Math.Floor(sample*unchecked((short)v[34])/256.0);driver.StepVoice(seq,0);Eq(expectedLevel,v.Level,"level slide wrap");Eq(period,v[4],"period slide wrap");Eq(W(period+delta),v.OutPeriod,"signed LFO high word");Eq(phase==0?(v[30]):phase,v[30],"LFO phase single subtraction");Eq(99,v.Duration,"duration tick");
  }
  // Reset preserves duration, stream, tempo, gate and loop counters. SCLEAR redirects subsequent writes but yield uses original voice.
  var s=new TestSeq(Data(0xFD,48,0,0xFF,10,0x34,0x12,0xFF,0,0,0));for(int i=0;i<24;i++)s.Voices[1].Words[i]=W(i+1);s.Voices[0].Stream=1024;s.Voices[0].Duration=1;driver.RunStream(s,0);Eq(0x1234,s.Voices[1].Level,"SCLEAR selects voice");Eq(8,s.Voices[1][14],"reset retains tempo");Eq(11,s.Voices[1][20],"reset retains gate");Eq(20,s.Voices[1][38],"reset retains loopA");Eq(21,s.Voices[1][40],"reset retains loopB");Eq(1035,s.Voices[0].Stream,"original voice stream cursor");Eq(1,s.Voices[0].Duration,"yield checks original duration");
  // SCALL has a single driver-wide return, SRET consumes it once.
  s=new TestSeq(Data(0xFC,0x10,4,0xFF,0,3,0));s.Arrangement.Data[1040]=0xFB;s.Voices[0].Stream=1024;s.Voices[0].Duration=1;driver.RunStream(s,0);Eq(3,s.Voices[0].Duration,"call return resumes");Eq(0,driver.ReturnAddress,"return slot consumed");s.Arrangement.Data[1050]=0xFB;s.Voices[0].Stream=1050;driver.State.VoiceTune[0]=7;driver.RunStream(s,0);Eq(0,s.Voices[0].Duration,"empty return stops");Eq(0,driver.State.VoiceTune[0],"idle clears tracker");
  s=new TestSeq(Data(0xFF,14,2,0,0x20,0x8D,7));s.Voices[0].Stream=1024;s.Voices[0].Duration=1;s.Voices[1][16]=20;driver.RunStream(s,0);Eq(14,s.Voices[0].Duration,"note low tempo scales");Eq(14,s.Voices[1].Duration,"note destination duration");Eq(0,s.Voices[1][20],"release lead longer than note disables gate");Eq(11950,s.Voices[1][4],"note octave and semitone");
  // Envelope set-level chains execute immediately; zero level stops slide, gate opens fifth release pair.
  s=new TestSeq(Data());var v0=s.Voices[0];v0.Duration=10;v0[20]=1;v0[22]=1500;v0[12]=9;Action<int,int> word=(i,n)=>{s.Arrangement.Data[i]=B(n);s.Arrangement.Data[i+1]=B(n>>8);};word(1516,0);word(1518,65535);word(1520,65530);word(1522,4);driver.StepVoice(s,0);Eq(0,v0.Level,"zero-level segment");Eq(65530,v0[12],"next envelope signed slide");Eq(4,v0[26],"release wait");Eq(24,v0[24],"release envelope position");
 }
